// Command side — strict, validated, transactional
class PlaceOrderCommandHandler {
  async handle(cmd: PlaceOrderCommand) {
    validateStrict(cmd.items);
    await db.transaction(() => saveOrder(cmd.items));
    await publishEvent("OrderPlaced", cmd); // keeps the read model in sync
  }
}

// Query side — fast, denormalized, optimized purely for reading
class OrderSummaryQueryHandler {
  async handle(query: GetOrderSummaryQuery) {
    // Reads from a separate, pre-denormalized read store — no joins needed
    return readDb.query("SELECT * FROM order_summary_view WHERE id=$1", [query.orderId]);
  }
}

// A subscriber keeps the read model updated from write-side events
onEvent("OrderPlaced", (order) => updateReadModel(order));
